#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> p;

void do_op(int x, int y, vector<pair<int,int>>& ops) {
    assert(x > 0 && y > 0 && x + y < n);
    ops.push_back({x, y});
    vector<int> np(n);
    // last y elements go first
    for (int i = 0; i < y; i++) np[i] = p[n - y + i];
    // middle elements next
    int mid = n - x - y;
    for (int i = 0; i < mid; i++) np[y + i] = p[x + i];
    // first x elements go last
    for (int i = 0; i < x; i++) np[y + mid + i] = p[i];
    p = np;
}

int main(){
    scanf("%d", &n);
    p.resize(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n; placed++) {
        int pos = -1;
        for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
        if (pos == placed) continue;

        // First, move element to position n-1 if it's not there
        if (pos != n - 1) {
            // Operation with x = pos+1, y = n-1-pos
            // x+y = n, need < n. So if pos > 0: x=pos, y=n-1-pos, x+y=n-1<n
            // Element at pos: it's in middle (x<=pos<n-y iff pos< pos+1, always true for pos>=x=pos... 
            // Actually pos >= x = pos is borderline. pos is exactly x, so it's start of middle.
            // Goes to y + pos - x = (n-1-pos) + pos - pos = n-1-pos... not n-1.

            // To move pos to n-1: use x=pos+1, y=n-pos-2 (if pos+1>0 and n-pos-2>0 and sum=n-1<n)
            // pos >= 1 (x>0) guaranteed since pos>placed>=0 and pos!=placed, and n-pos-2>0 => pos<n-2
            if (pos >= 1 && pos < n - 1) {
                // element at pos: pos < x=pos+1, so it's in prefix, goes to n-x+pos = n-pos-1+pos = n-1
                do_op(pos + 1, n - pos - 2, ops);
                pos = n - 1;
            } else if (pos == 0) {
                // x=1,y=1 if n>2: element at 0 goes to n-1
                if (n > 2) { do_op(1, n - 2, ops); pos = n - 1; }
            }
        }
        // Now element is at n-1. Move to position placed.
        if (pos == n - 1 && placed != n - 1) {
            // Use y=1: element at n-1 goes to position 0. Then if placed=0, done.
            // Use x=n-1-placed, y=1: element at n-1 goes to pos 0. x+y=n-placed<n if placed>0
            // Actually element at n-1 with y=1: i>=n-y=n-1, goes to i-(n-1)=0. Then prefix is [0..x-1], goes to end.
            // Result: [p[n-1]], middle, prefix. Element at position 0.
            // We want it at placed. Use x = placed+1... no. Let me use x=n-1-placed, y=1.
            if (placed > 0) { do_op(n - 1 - placed, 1, ops); }
            else { do_op(1, 1, ops); } // placed==0, n>2
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
